export function routeToHash(route: Route): string {
  switch (route.mode) {
    case 'main-menu':
      return '';
    case 'single-menu':
      return '#singleplayer';
    case 'deck-builder':
      return '#deck-builder';
    case 'quick-setup':
      return '#quick';
    case 'quick-opponent':
      return `#quick-opponent=${route.pool}`;
    case 'quick-game':
      return `#quick=${route.pool}${route.companion ? `&companion=${route.companion}` : ''}`;
    case 'campaign':
      return '#campaign';
    case 'campaign-game':
      return `#campaign=${route.difficulty}`;
    case 'multi-menu':
      return '#multiplayer';
    case 'hotseat':
      return '#hotseat';
    case 'online':
