export function findGameType(players: RingQueue<Player>): GameType | undefined {
  const gameTypeCandidates = players.asList().map((p) => new GameType(p.reservation, p));

  const missingReservations = gameTypeCandidates.find((c) => c.reservation === Reservation.None);
  if (missingReservations) {
    return undefined;
  }

  const solos = gameTypeCandidates.filter((c) => !nonSoloTypes.includes(c.reservation));

  if (solos.length > 0) {
    return solos[0];
  }

  const wedding = gameTypeCandidates.find((c) => c.reservation === Reservation.Wedding);

  return wedding || GameType.normalGame();
}

export function dealCardsFor(
  playerCount: number,
  deck: Readonly<Deck>
): [Deck, Player[]] {
  let newDeck = deck.slice();
  const players = [];
  for (let i = 0; i < playerCount; i++) {
    let player;
    [newDeck, player] = dealCards(newDeck);
    players.push(player);
  }
  return [newDeck!, players];
}

export function dealHand(rng: Rng, deck: readonly SideCard[]): SideCard[] {
  const shuffled = [...deck];
  rng.shuffle(shuffled);
  const hand: SideCard[] = [];
  const seen = new Set<string>();
  for (const c of shuffled) {
    if (hand.length >= HAND_SIZE) break;
    if (seen.has(c.code)) continue;
    seen.add(c.code);
    hand.push(c);
  }
  for (let i = 0; hand.length < HAND_SIZE && shuffled.length > 0; i++) {
    hand.push(shuffled[i % shuffled.length]);
  }
  return hand;
}

export function aHandWithout(numberOfCards: number, excludedCard: Card) {
