export class MainDeck {
  private cards: number[] | null = null;

  constructor(
    private readonly rng: Rng,
    private readonly copies = 4,
  ) {}

  private refill(): void {
    const cards: number[] = [];
    for (let v = MAIN_DECK_MIN; v <= MAIN_DECK_MAX; v++) {
      for (let i = 0; i < this.copies; i++) cards.push(v);
    }
    this.rng.shuffle(cards);
    this.cards = cards;
  }

  draw(): number {
    if (!this.cards || this.cards.length === 0) this.refill();
    return this.cards!.pop()!;
  }

  get remaining(): number {
    return this.cards ? this.cards.length : 0;
  }
}

export class goodyAnnouncement implements announcementRules {
  announcementToMake(possibleAnnouncements: Set<Announcement>, hand: Hand): Announcement | null {
    if (
      [...possibleAnnouncements].includes(Announcement.Kontra) ||
      [...possibleAnnouncements].includes(Announcement.Re)
    ) {
      let counter = 0;
      if (hand.getBlankAces().length > 0) counter++;
      if (hand.trumps().length >= 7) counter++;
      if (hand.cards.filter((c) => c.is(ten.of(Suit.Hearts))).length === 2) counter++;
      counter += hand.getMissingSuites().length;
      return counter > 2 ? [...possibleAnnouncements][0] : null;
    }
    return null;
  }
}

export class SeededRng implements Rng {
  private state: number;

  constructor(seed = Date.now() >>> 0) {
    this.state = seed >>> 0;
  }

  private next(): number {

    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  randint(a: number, b: number): number {
    return a + Math.floor(this.next() * (b - a + 1));
  }

  shuffle<T>(list: T[]): void {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
  }

  sample<T>(list: readonly T[], k: number): T[] {
    const pool = [...list];
    this.shuffle(pool);
    return pool.slice(0, k);
  }
}

export class Card {
  id: number;
  rank: Rank;
  suit: Suit;

  constructor(rank: Rank, suit = Suit.Clubs, id = 0) {
    this.rank = rank;
    this.suit = suit;
    this.id = id;
  }

  get value() {
    return values[this.rank];
  }

  get cardId() {
    return `${this.rank}-${this.suit}-${this.id}`;
  }

  of(suit: Suit) {
    return new Card(this.rank, suit);
  }

  first() {
    return new Card(this.rank, this.suit, 0);
  }

  second() {
    return new Card(this.rank, this.suit, 1);
  }

  isTrump() {
    return trumps.some((c) => c.is(this));
  }

  beats(anotherCard: Card | undefined) {
    if (!anotherCard) {
      return false;
    }

    return this.compareTo(anotherCard) < 0;
  }

  compareTo(anotherCard: Card) {
    const thisIsTrump = this.isTrump();
    const otherCardIsTrump = anotherCard.isTrump();

    if (thisIsTrump && !otherCardIsTrump) {
      return -1;
    }

    if (!thisIsTrump && otherCardIsTrump) {
      return 1;
    }

    if (thisIsTrump && otherCardIsTrump) {
      return trumps.findIndex((c) => c.is(this)) - trumps.findIndex((c) => c.is(anotherCard));
    }

    if (!thisIsTrump && !otherCardIsTrump) {
      if (this.suit === anotherCard.suit) {
        return anotherCard.value - this.value;
      }
    }

    return 0;
  }

  equals(anotherCard: Card | undefined) {
    if (!anotherCard) {
      return false;
    }

    return (
      this.rank == anotherCard.rank && this.suit == anotherCard.suit && this.id == anotherCard.id
    );
  }

  is(anotherCard: Card) {
    return this.rank === anotherCard.rank && this.suit === anotherCard.suit;
  }
}

export class PartyBuilder {
  party: PartyName;
  players: Player[];
  announcements: Set<Announcement>;
  extras: Extra[];
  points: number;

  constructor(party: PartyName) {
    this.party = party;
    this.players = [];
    this.announcements = new Set();
    this.extras = [];
    this.points = 0;
  }

  withPlayer(player: Player) {
    this.players.push(player);
    return this;
  }

  withAnnouncement(announcements: Announcement) {
    this.announcements.add(announcements);
    return this;
  }

  withExtra(extra: Extra) {
    this.extras.push(extra);
    return this;
  }

  withPoints(points: number) {
    this.points = points;
    return this;
  }

  build() {
    if (this.players.length === 0) {
      this.players = [
        new PlayerBuilder(`a ${this.party} player`).withParty(this.party).build(),
        new PlayerBuilder(`another ${this.party} player`).withParty(this.party).build(),
      ];
    } else {
      this.players.forEach((player) => {
        player.isRe = () => this.party === PartyName.Re;
      });
    }

    const createdParty = new Party(this.party, ...this.players);
    createdParty.announcements = () => [...this.announcements];
    createdParty.extras = () => this.extras;
    createdParty.points = () => this.points;

    return createdParty;
  }
}

export class PlayerBuilder {
  name: string
  points: number = 0
  extras: Extra[] = []
  party: string = 're'
  id: string = uuidv4()

  constructor(name: string) {
    this.name = name
  }

  withPoints(points: number): PlayerBuilder {
    this.points = points
    return this
  }

  withParty(party: string): PlayerBuilder {
    this.party = party
    return this
  }

  withExtra(extra: Extra): PlayerBuilder {
    this.extras.push(extra)
    return this
  }

  withId(id: string): PlayerBuilder {
    this.id = id
    return this
  }

  build() {
    const player = new Player(this.name)
    player.isRe = () => this.party === PartyName.Re
    player.isKontra = () => this.party !== PartyName.Re
    player.points = () => this.points
    player.trickStack.extras = () => this.extras
    player.id = this.id
    return player
  }
}

function isBorderProvince(provinceId: string, nationId: string, state: GameState): boolean {
  return getAdjacentProvinceIds(provinceId, state).some((adjId) => {
    const adj = state.provinces.find((p) => p.id === adjId);
    return adj && adj.ownerId !== nationId;
  });
}

export function getRandomValueBetween(lower_bound: number, upper_bound: number): number {
  if (lower_bound > upper_bound) {
    swapValues(lower_bound, upper_bound);
  }
  return lower_bound + Math.floor(Math.random() * (upper_bound - lower_bound + 1));
}

export function wasAttackedBy(state: GameState, viewer: LeaderId, attacker: LeaderId): boolean {
  const me = state.leaders[viewer];
  if (!me) return false;
  return (me.grudge[attacker] ?? 0) > 0 || (me.recentAggressionFrom[attacker] ?? 0) > 0;
}

function startTurn(state: GameState): void {
  const player = currentPlayer(state);
  emit(state, { kind: 'turn_start', actor: player.id, at: null });

  // Ingresos del día: ayuntamientos y minas.
  let income = { ...EMPTY_RESOURCES };
  for (const town of townsOf(state, player.id)) {
    income = addResources(income, { gold: dailyIncome(town) });
    town.builtToday = false;
  }
  for (const obj of state.map.objects) {
    if (obj.kind === 'mine' && obj.owner === player.id) {
      income = addResources(income, { [obj.resource]: MINE_YIELD[obj.resource] });
    }
  }
  player.resources = addResources(player.resources, income);

  for (const hero of heroesOf(state, player.id)) {
    hero.movePoints = maxMovePoints(hero);
    // El maná se recupera poco a poco, salvo en un pueblo con gremio.
    const enPueblo = townsOf(state, player.id).some(
      (t) => pointKey(t.at) === pointKey(hero.at) && mageGuildLevel(t) > 0,
    );
    hero.mana = enPueblo ? maxMana(hero) : Math.min(maxMana(hero), hero.mana + 1);
    // Y mira alrededor al levantarse: un héroe quieto también ve. Sin esto, su
    // recuerdo de la mina que tiene al lado sería del día en que llegó.
    revealAround(state, hero);
  }
}

export function getIntoVehicle(state: GameMap, action: GetIntoVehicleReducerAction) {
  const { unit, vehicle } = action;

  state.deOccupyCell(unit.getRoundedPosition());
  unit.getIntoVehicle(vehicle);
  unit.setRotation(vehicle.rotation, false);
  vehicle.assignDriver(unit);

  const turnOnSfx = state.createSfx([vehicle.dictEntity.sfx["turnOn"].src], 1);
  const idleSfx = state.createSfx([vehicle.dictEntity.sfx["idle"].src], 1);

  if (turnOnSfx) {
    const stopTime = turnOnSfx.buffer!.duration * 1000 - 265;

    if (idleSfx) {
      window.setTimeout(() => {
        vehicle.currentPlayingSfx["idle"] = idleSfx;

        idleSfx.loop = true;
        idleSfx.start();
      }, stopTime);
