function validateMeta(meta: unknown, errors: string[]): meta is ScenarioMeta {
  if (!isObject(meta)) {
    errors.push('meta: must be an object');
    return false;
  }

  if (!isString(meta.id) || meta.id.length === 0) errors.push('meta.id: must be a non-empty string');
  if (!isString(meta.name) || meta.name.length === 0) errors.push('meta.name: must be a non-empty string');
  if (!isString(meta.description)) errors.push('meta.description: must be a string');
  if (!isNumber(meta.turnLimit) || meta.turnLimit < 1) errors.push('meta.turnLimit: must be a positive number');
  if (!isNumber(meta.exileWindowTurns) || meta.exileWindowTurns < 0) errors.push('meta.exileWindowTurns: must be a non-negative number');
  if (!isNumber(meta.exileRestoreCost) || meta.exileRestoreCost < 0) errors.push('meta.exileRestoreCost: must be a non-negative number');
  if (!isNumber(meta.siegeTurns) || meta.siegeTurns < 1) errors.push('meta.siegeTurns: must be a positive number');
  if (!isNumber(meta.relationDecayPerTurn) || meta.relationDecayPerTurn < 0) errors.push('meta.relationDecayPerTurn: must be a non-negative number');

  if (meta.majorBattleThreshold !== undefined && !isNumber(meta.majorBattleThreshold)) {
    errors.push('meta.majorBattleThreshold: must be a number if provided');
  }

  validateVictoryConditions(meta.victoryConditions, errors);

  if (meta.developmentOutputTable !== undefined) {
    validateDevelopmentOutputTable(meta.developmentOutputTable, errors);
  }

  return true;
}

export function checkFlankingStatus(facingDir: HexDirection, attackFromDir: HexDirection): HexFlankStatus {
  if (facingDir === HexDirection.NONE || attackFromDir === HexDirection.NONE) {
    return HexFlankStatus.NONE;
  }

  // Directions
  //     \ 3 |  2 /
  //      \/  \ /
  //    4 |   |  1
  //     /\  / \
  //   / 5 |  6 \
  // If the unit is facing direction 4 and
  // - the attack is coming from direction 2 or 6, it is a flanking attack.
  // - the attack is coming from direction 1, it is a backstab.
  // - the attack is coming from other directions, it is a normal attack.

  const relativeDir = (6 + attackFromDir - facingDir) % 6 + 1;
  if (relativeDir === 3 || relativeDir === 5) {
    return HexFlankStatus.FLANK;
  } else if (relativeDir === 4) {
    return HexFlankStatus.BACKSTAB;
  }

  return HexFlankStatus.NONE;
}

function pickStrongestRival(
  state: GameState, viewer: LeaderId, others: LeaderId[],
): LeaderId | undefined {
  if (others.length === 0) return undefined;
  return others.reduce((best, t) =>
    threatScore(state, viewer, t) > threatScore(state, viewer, best) ? t : best,
  );
}

export class TurnChangeDisplay {

  static DEFAULT_FONT_STYLE: TextOptions = { style: { fill: { color: '#dddd77', alpha: 1 }, fontSize: 42, align: 'left' } };
  static DEFAULT_DURATION_IN_MILLIS: number = 750;
  static END_OF_BATTLE_DURATION_IN_MILLIS: number = 5000;

  private turnChangeText = new Text({ ...TurnChangeDisplay.DEFAULT_FONT_STYLE, text: this.message });
  private alpha: number = 1;
  private startingDurationInMillis: number = TurnChangeDisplay.DEFAULT_DURATION_IN_MILLIS;
  private bannerSprite?: Sprite = undefined;

  private window = new Container();

  public constructor(
    private message: string,
    private view: Container,
    public remainingDurationInMillis: number,
    coords: Coords,
    private uiSheet?: Spritesheet,
    private texture?: Texture
  ) {
    if (!this.uiSheet) {
      throw new Error('uiSheet is required');
    }

    this.startingDurationInMillis = remainingDurationInMillis;

    const windowBg = new NineSliceSprite({
      texture: this.uiSheet.textures['panel.png'],
      leftWidth: 15,
      topHeight: 15,
      rightWidth: 15,
      bottomHeight: 15,
    });
    windowBg.width = 400;
    windowBg.height = 120;
    this.window.addChild(windowBg);

    const bannerBg = new NineSliceSprite({
      texture: this.uiSheet.textures['progress_bg.png'],
      leftWidth: 5,
      topHeight: 5,
      rightWidth: 5,
      bottomHeight: 5
    });
    bannerBg.width = 128 + 10;
    bannerBg.height = 128 + 10;
    bannerBg.position = { x: (400 - 128) / 2 - 5, y: 80 - 5 };
    this.window.addChild(bannerBg);

    this.window.position = coords;

    if (this.texture) {
      this.bannerSprite = new Sprite(this.texture);
      this.bannerSprite.position = { x: (400 - 128) / 2, y: 80 };
      this.bannerSprite.width = 128;
      this.bannerSprite.height = 128;
      this.window.addChild(this.bannerSprite);
    }

    this.turnChangeText.position = { x: 20, y: 20 };
    this.turnChangeText.text = "" + message.toString();
    this.window.addChild(this.turnChangeText);
    this.view.addChild(this.window);
  }

  public update(delta: number) {
    if (delta == 0 || this.startingDurationInMillis == 0) {
      return;
    }

    if (this.remainingDurationInMillis < 0.5 * this.startingDurationInMillis) {
      this.alpha = this.remainingDurationInMillis * 2 / this.startingDurationInMillis;
      this.window.alpha = this.alpha;
    }

    this.remainingDurationInMillis -= delta;

    if (this.remainingDurationInMillis <= 0) {
      this.view.removeChild(this.window);
      this.window.destroy({ children: true });
    }
  }
}

export class VisualLoader {
  private scene: Phaser.Scene;
  private progressBar?: Phaser.GameObjects.Graphics;
  private progressBgRect?: Phaser.Geom.Rectangle;
  private progressRect?: Phaser.Geom.Rectangle;

  constructor(scene: any) {
    this.scene = scene;
  }

  /**
   * createProgressBar
   */
  public createProgressBar() {
    const main = this.scene.cameras.main;

    this.progressBgRect = new Rectangle(0, 0, 0.5 * main.width, 50);

    Rectangle.CenterOn(this.progressBgRect, 0.5 * main.width, 0.5 * main.height);

    this.progressRect = Rectangle.Clone(this.progressBgRect);
    this.progressBar = this.scene.add.graphics();
  }

  /**
   * onLoadComplete
   */
  public onLoadComplete(loader: any, totalComplete: number, totalFailed: number) {
    // console.debug('complete', totalComplete);
    // console.debug('failed', totalFailed);
    if (!this.progressBar) { return; }
    this.progressBar.destroy();
  }

  /**
   * onLoadProgress
   */
  public onLoadProgress(progress: number) {
    // console.debug('progress', progress);
    if (!this.progressBar || !this.progressBgRect || !this.progressRect) { return; }

    const { red, white } = hexColors;

    this.progressRect.width = progress * this.progressBgRect.width;

    this.progressBar
      .clear()
      .fillStyle(hexColors.darkGray)
      .fillRectShape(this.progressBgRect)
      .fillStyle(this.scene.load.totalFailed ? red : white)
      .fillRectShape(this.progressRect);
  }
}

