export class FogOfWar {
  private canvas: OffscreenCanvas;
  private ctx: OffscreenCanvasRenderingContext2D;
  private bg = "";

  private readonly size: Size2D;
  constructor(props: { size: Size2D }) {
    this.size = props.size;
    this.canvas = new OffscreenCanvas(props.size.width, props.size.height);
    this.ctx = this.canvas.getContext("2d")!;
  }

  async render(hero: Unit): Promise<FogOfWar["bg"]> {
    const hideFill = `rgba(0, 0, 0, ${constants.FOG_OF_WAR_OPACITY})`;
    const { ctx } = this;
    const { width, height } = this.size;

    ctx.clearRect(0, 0, width, height);
    ctx.globalCompositeOperation = "source-over";

    ctx.fillStyle = hideFill;
    ctx.lineWidth = 0;
    ctx.fillRect(0, 0, width, height);

    ctx.globalCompositeOperation = "destination-out";

    const { x, y } = hero.position.grid;

    ctx.beginPath();
    ctx.moveTo(x, y);

    for (const ray of hero.fieldOfView.rays) {
      ctx.lineTo(
        Math.round(ray.n.grid.x * ray.len.grid) + ray.position.grid.x,
        Math.round(ray.n.grid.y * ray.len.grid) + ray.position.grid.y,
      );
    }

    ctx.lineTo(x, y);
    ctx.closePath();
    ctx.ellipse(x, y, 1, 3, -Math.PI / 4, 0, 2 * Math.PI);
    ctx.fill();

    //
    const blob = await this.canvas.convertToBlob();

    this.bg = window.URL.createObjectURL(blob);

    return this.bg;
  }
}

export function normalizeVector(current: Vector2, target: Vector2): Vector2 {
	const dx = target.x - current.x;
	const dy = target.y - current.y;
	const distance = Math.sqrt(dx * dx + dy * dy);
	return distance ? new Vector2(dx / distance, dy / distance) : new Vector2(0, 0);
}

function buildRouteLine(map: MapDef, field: SectorField): Graphics {
  const g = new Graphics();
  // One normaliser for the board, matching `routeDistance` — see the argument
  // there for why the ramp is measured back from the goal rather than forward
  // from a spawn, and why a short lane starting part-lit is the truth.
  const longest = Math.max(...map.routes.map((r) => r.length));

  for (const route of map.routes) {
    const wp = route.waypoints;
    let travelled = 0;

    for (let i = 1; i < wp.length; i++) {
      const a = wp[i - 1]!;
      const b = wp[i]!;
      const steps = Math.abs(b.x - a.x) + Math.abs(b.y - a.y);

      // The midpoint's distance from the goal sets the segment's colour, so the
      // ramp follows the road rather than the screen.
      const t = longest > 0 ? 1 - (route.length - travelled - steps / 2) / longest : 0;
      travelled += steps;

      g.moveTo(a.x * TILE_PX, a.y * TILE_PX)
        .lineTo(b.x * TILE_PX, b.y * TILE_PX)
        .stroke({
          width: 2,
          cap: 'round',
          join: 'round',
          color: mixColor(field.lineNear, field.lineFar, t),
          alpha: field.lineNearAlpha + (field.lineFarAlpha - field.lineNearAlpha) * t,
        });
    }
  }

  return g;
}

function hook(
  spawn: GridPosition, goal: GridPosition,
  _rows: number, cols: number,
  rand: () => number, minR: number, maxR: number, midC: number,
): GridPosition[] {
  const hookCol = randInt(rand, midC + 2, cols - 4);
  const hookRow = spawn.row <= (minR + maxR) / 2 ? randInt(rand, maxR - 2, maxR) : randInt(rand, minR, minR + 2);
  const backCol = randInt(rand, midC - 2, midC + 1);

  return [
    spawn,
    { row: spawn.row, col: hookCol },         // go right
    { row: hookRow, col: hookCol },            // go down/up
    { row: hookRow, col: backCol },            // hook back left
    { row: goal.row, col: backCol },           // go to goal row
    goal,                                       // go right to goal
  ];
}

function distBulletToEnemy(bullet: Bullet, enemy: Enemy) {
  let dist;

  switch (bullet.type) {
    case BULLETS.CIRCLE:
    case BULLETS.SLOW:
    case BULLETS.FIRE:
      dist = calculateDistance(bullet.x, bullet.y, enemy.x, enemy.y);
      break;
    case BULLETS.LASER:
      if ((bullet as Laser).target.id === enemy.id) {
        dist = 0;
      }
      break;
  }
  return dist;
}

function getRotatedRectVertices(rect: Rect2D, angleInDegrees: number): Vector2[] {
	const centerX = (rect.x1 + rect.x2) / 2;
	const centerY = (rect.y1 + rect.y2) / 2;
	const width = rect.x2 - rect.x1;
	const height = rect.y2 - rect.y1;

	// We already have angleToTarget for radians conversion
	const angle = angleToTarget(
		new Vector2(0, 0),
		new Vector2(
			Math.cos((angleInDegrees * Math.PI) / 180),
			Math.sin((angleInDegrees * Math.PI) / 180)
		)
	);

	// We already have getDirectionFromAngle
	const direction = getDirectionFromAngle(angle);

	// Calculate vertices using existing Vector2 class
	return [
		new Vector2(-width / 2, -height / 2),
		new Vector2(width / 2, -height / 2),
		new Vector2(width / 2, height / 2),
		new Vector2(-width / 2, height / 2)
	].map((v) => {
		// Rotate using direction vector
		return new Vector2(
			v.x * direction.x - v.y * direction.y + centerX,
			v.x * direction.y + v.y * direction.x + centerY
		);
	});
}

export function renderInspector(w: World, t: Tower): string {
  const d = TOWERS[t.defId];
  const s = t.stats;
  const nextDamage = nextStats(t, 'damage', tierCeiling(w))?.damage ?? null;

  // Iconic, with **the active mode labelled** — not labels-on-hover.
  //
  // Four unlabelled glyphs would be unguessable (Strong and Close especially),
  // `title` never fires on touch, and this control mutates game state so a
  // mis-click has a cost. Naming only the selected one costs exactly one word,
  // is self-teaching — the player sees "First" beside its glyph and learns the
  // glyph — and works without a pointer. `aria-label` on all four regardless.
  const modes = TARGET_MODES.map((m) => {
    const on = t.targeting === m;
    return (
      `<button data-act="target" data-mode="${m}" class="${on ? 'on' : ''}"` +
      // No `title`: it duplicates the aria-label, and the active mode is
      // already spelled out beside its glyph — which is the affordance that
      // works without a pointer.
      ` aria-label="${TARGET_LABEL[m]}">${TARGET_GLYPH[m]}` +
      (on ? `<span>${TARGET_LABEL[m]}</span>` : '') +
      `</button>`
    );
  }).join('');

  return (
    `<div class="inspector">` +
    // Portrait column: the station wearing its real collar at full size, so the
    // board's positional upgrade code is taught here rather than by a 13px
    // afterthought on a button. The board only has to jog this memory.
    `<div class="portrait t-${t.defId}">${stationIcon(t.defId, 40)}` +
    `${collarDial(t.tiers, BALANCE.upgrade.maxTier, 56)}` +
    `<span class="mk">Mk ${'I'.repeat(visualTier(t))}</span></div>` +
    `<div class="body">` +
    `<div class="head t-${t.defId}"><b>${d.name}</b>` +
    // Tile coordinates dropped — the one fact here nobody has ever needed.
    // Damage dealt stays in the `title` rather than becoming text: this is the
    // inspector, read mid-wave, and it is held to a hard ten-word budget that
    // tools/check.ts enforces. The words go to the armed panel instead.
    `<span class="blurb" title="${Math.round(t.damageDealt)} damage dealt">` +
    `${t.kills} ${t.kills === 1 ? 'kill' : 'kills'}</span></div>` +
    // Live stats, not the def: this is where an effect purchase becomes visible
    // in numbers, including the secondary dial the upgrade card omits. One row
    // for both chip groups — the inspector's height budget has no room for two.
    `<div class="chipline t-${t.defId}">${mechanicChips(s)}${axisChips(s, false, effectiveInterval(t))}</div>` +
    renderArmourLine(w, t, nextDamage) +
    `</div>` +
    `<div class="upgrades">${renderPathButtons(w, t)}</div>` +
    `<div class="actions"><div class="seg targeting">${modes}</div>` +
    `<button class="btn" data-act="sell">Sell ${sellValue(t)}</button></div>` +
    `</div>`
  );
}

