		return {
			x1: this.gameXOffset,
			y1: this.gameYOffset,
			x2: this.width,
			y2: this.height
		};
	}

	isEntityInScreen(entity: Entity): boolean {
		const { x1, y1, x2, y2 } = this.screenBounds;
		const { x, y } = entity.position;

		return (
			x + entity.width / 2 > x1 &&
			x - entity.width / 2 < x2 &&
			y + entity.height > y1 &&
			y - entity.height < y2
		);
	}
}

